const places={甘孜:{region:'SICHUAN · GANZI',description:'雪山、草甸与山谷里的村落，构成一幅辽阔的高原画卷。',tags:['雪山远眺','高原风光','山间漫游']},荔波:{region:'GUIZHOU · LIBO',description:'沿着水声走进青绿深处，在林间慢行，在桥边停留。',tags:['喀斯特山水','森林漫步','亲近自然']},腾冲:{region:'YUNNAN · TENGCHONG',description:'古镇石巷、温泉热气与边地风物，把时光酿得柔软。',tags:['古镇漫游','温泉时光','边地风物']},阿尔山:{region:'INNER MONGOLIA · ARXAN',description:'走近森林与火山地貌，在四季变换中找到不同的颜色。',tags:['森林四季','火山地貌','小城散步']},陇川:{region:'YUNNAN · LONGCHUAN',description:'从广宋机场落地，沿着边境风物前往陇川县城与瑞丽。',tags:['边境风物','瑞丽联运','小城慢游']},兰坪:{region:'YUNNAN · LANPING',description:'飞越横断山脉，抵达兰坪白族普米族自治县。',tags:['三江秘境','民族文化','高原山川']},凤庆:{region:'YUNNAN · FENGQING',description:'走进滇红茶乡，在山岭与茶园之间慢慢生活。',tags:['滇红茶乡','山间小城','人文寻访']},昆明:{region:'YUNNAN · KUNMING',description:'从春城出发，连接云南山川之间的小地方。',tags:['中转枢纽','春城','耀天起点']}};
const routes={成都:['甘孜','荔波'],昆明:['陇川','兰坪','凤庆'],重庆:['荔波','甘孜'],兰坪:['昆明'],陇川:['昆明'],凤庆:['昆明']};const airportLabels={昆明:'昆明 · 长水国际机场',陇川:'陇川（瑞丽）· 广宋机场',兰坪:'兰坪 · 丰华通用机场',凤庆:'凤庆 · 中和机场'};const origin=document.querySelector('#origin'),destination=document.querySelector('#destination');
function updateOptions(selectedDestination){destination.replaceChildren(...routes[origin.value].map(city=>new Option(airportLabels[city]||city+' · '+places[city].tags[0],city)));if(selectedDestination&&routes[origin.value].includes(selectedDestination))destination.value=selectedDestination;document.querySelector('#route-result').hidden=true}origin.addEventListener('change',()=>updateOptions());updateOptions();
document.querySelector('.swap').addEventListener('click',()=>{const previousOrigin=origin.value;const previousDestination=destination.value;const reverseOrigin=[...origin.options].some(option=>option.value===previousDestination);if(!reverseOrigin||!routes[previousDestination]?.includes(previousOrigin)){document.querySelector('.swap').title='这条航线暂不支持反向选择';return}origin.value=previousDestination;updateOptions(previousOrigin);document.querySelector('.swap').title='交换出发地与目的地'});
const departureDate=document.querySelector('#travel-date'),returnDate=document.querySelector('#return-date'),dateSeparator=document.querySelector('.date-separator'),dateField=document.querySelector('.date-field');
function localDateValue(date){const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`}
function addCalendarMonths(date,months){const result=new Date(date.getFullYear(),date.getMonth()+months,1);const lastDay=new Date(result.getFullYear(),result.getMonth()+1,0).getDate();result.setDate(Math.min(date.getDate(),lastDay));return result}
const bookingToday=new Date(),bookingStart=localDateValue(bookingToday),bookingEnd=localDateValue(addCalendarMonths(bookingToday,10));departureDate.min=bookingStart;departureDate.max=bookingEnd;returnDate.min=bookingStart;returnDate.max=bookingEnd;
function updateTripType(){const isRoundTrip=document.querySelector('input[name="trip"]:checked').value==='round-trip';returnDate.hidden=!isRoundTrip;dateSeparator.hidden=!isRoundTrip;returnDate.required=isRoundTrip;dateField.classList.toggle('round-trip',isRoundTrip);document.querySelector('#date-field-label').textContent=isRoundTrip?'去程 — 返程':'日期';if(isRoundTrip&&departureDate.value){returnDate.min=departureDate.value;if(returnDate.value&&returnDate.value<departureDate.value)returnDate.value=departureDate.value}}
document.querySelectorAll('input[name="trip"]').forEach(radio=>radio.addEventListener('change',updateTripType));departureDate.addEventListener('change',()=>{returnDate.min=departureDate.value||bookingStart;if(returnDate.value&&returnDate.value<returnDate.min)returnDate.value=returnDate.min});updateTripType();
const heroWord=document.querySelector('#hero-word'),heroWords=['家','风景'],scrambleChars='云山川海风景故乡远方星河林野归途人间烟火';let heroWordIndex=0;
function scrambleHeroWord(){heroWordIndex=(heroWordIndex+1)%heroWords.length;const target=heroWords[heroWordIndex],start=performance.now(),duration=900;function frame(now){const progress=Math.min((now-start)/duration,1),settled=Math.floor(progress*(target.length+1));heroWord.textContent=[...target].map((char,index)=>index<settled?char:scrambleChars[Math.floor(Math.random()*scrambleChars.length)]).join('');if(progress<1)requestAnimationFrame(frame);else heroWord.textContent=target}requestAnimationFrame(frame)}
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(scrambleHeroWord,5000);
document.querySelector('#route-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const params=new URLSearchParams({from:origin.value,to:destination.value,date:departureDate.value,trip:document.querySelector('input[name="trip"]:checked').value,passengers:document.querySelector('#interest').value});if(returnDate.value)params.set('return',returnDate.value);window.location.href=`results.html?${params}`});
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const filter=button.dataset.filter;document.querySelector('.destination-grid').classList.toggle('filtered',filter!=='all');document.querySelectorAll('.destination-card').forEach(card=>card.hidden=filter!=='all'&&!card.dataset.category.split(' ').includes(filter))}));
const dialog=document.querySelector('#destination-dialog');let selectedCity='';let saved=[];try{saved=JSON.parse(localStorage.getItem('yunxiang-favorites')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}
function setSaveLabel(){document.querySelector('#save-destination').textContent=saved.includes(selectedCity)?'已收藏这份向往 ♥':'收藏这个目的地 ♡'}
document.querySelectorAll('.destination-card').forEach(card=>card.addEventListener('click',()=>{selectedCity=card.dataset.city;const place=places[selectedCity];document.querySelector('#dialog-title').textContent=selectedCity;document.querySelector('#dialog-region').textContent=place.region;document.querySelector('#dialog-description').textContent=place.description;document.querySelector('#dialog-tags').replaceChildren(...place.tags.map(t=>{const el=document.createElement('span');el.textContent=t;return el}));setSaveLabel();dialog.showModal()}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
document.querySelector('#save-destination').addEventListener('click',()=>{saved=saved.includes(selectedCity)?saved.filter(c=>c!==selectedCity):[...saved,selectedCity];try{localStorage.setItem('yunxiang-favorites',JSON.stringify(saved))}catch{}setSaveLabel()});
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.primary-nav');
const navBackdrop=document.createElement('button');navBackdrop.type='button';navBackdrop.className='mobile-nav-backdrop';navBackdrop.setAttribute('aria-label','关闭导航');document.body.appendChild(navBackdrop);
const setMenu=open=>{nav.classList.toggle('open',open);navBackdrop.classList.toggle('open',open);document.body.classList.toggle('mobile-nav-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'关闭导航':'打开导航');toggle.textContent=open?'×':'☰'};
toggle.addEventListener('click',()=>setMenu(!nav.classList.contains('open')));navBackdrop.addEventListener('click',()=>setMenu(false));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});window.addEventListener('resize',()=>{if(window.innerWidth>1000)setMenu(false)});document.querySelector('#year').textContent=new Date().getFullYear();

